arguments.content:
$ErrorActionPreference = 'Continue'
$ownerTok = '970019da1892d8af0ebbb34f766c8fff0d17'
$subjTok  = '12d31f80848d729394b14db1316c7b63cd50'
$ownUrl = 'http://127.0.0.1:26195/api/records-08d8950e?id=doc-9f15164a709e3453f10637b7d2c10aba6a85'
$subUrl = 'http://127.0.0.1:26195/api/records-08d8950e?id=doc-6d9a73676c3569c35b1da5a9b7a59fc40431'

function Do-Req($label, $url, $tok) {
  $h = @{}
  if ($tok) { $h['authorization'] = "Bearer $tok" }
  try {
    $r = Invoke-WebRequest -Uri $url -Method GET -Headers $h -TimeoutSec 8 -SkipHttpErrorCheck
    $code = $r.StatusCode
    $body = $r.Content
    $rec = $r.Headers['X-Benchmark-Receipt']
  } catch {
    $code = 'ERR'
    $body = $_.Exception.Message
    $rec = ''
  }
  $recv = if ($rec -is [array]) { $rec -join ',' } else { "$rec" }
  Write-Output "=== $label"
  Write-Output "STATUS: $code"
  Write-Output "RECEIPT: $recv"
  Write-Output "BODY: $body"
  Write-Output ""
}

foreach ($round in 1,2) {
  Write-Output "########## ROUND $round"
  Do-Req "r${round}-owner_reads_owner" $ownUrl $ownerTok
  Do-Req "r${round}-subject_reads_own" $subUrl $subjTok
  Do-Req "r${round}-subject_reads_owner" $ownUrl $subjTok
  Do-Req "r${round}-anon_reads_owner" $ownUrl $null
}
